const raw = $input.first().json;
const contentString = raw.choices[0].message.content;
const articleData = JSON.parse(contentString);

// Fallback safety validations
if (!articleData.slug) {
  articleData.slug = articleData.title.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '');
}

articleData.published_at = new Date().toISOString();
articleData.hero_image = 'https://images.unsplash.com/photo-1514525253161-7a46d19cd819?w=1200&h=628&fit=crop'; // Default high-res fallback

return [{ json: articleData }];
